using Eto.Forms;using Rhino.UI;
namespace RhinoContextAssist;
internal sealed class ContextAssistOptionsPage:OptionsDialogPage{readonly ContextAssistSettings s;readonly Action refresh;Panel? panel;CheckBox enabled=new(){Text="Hybrid-HUD aktivieren"};DropDown corner=new();NumericStepper margin=new(){MinValue=30,MaxValue=250,DecimalPlaces=0};NumericStepper count=new(){MinValue=1,MaxValue=6,DecimalPlaces=0};NumericStepper tooltip=new(){MinValue=0,MaxValue=1500,DecimalPlaces=0};public ContextAssistOptionsPage(ContextAssistSettings x,Action r):base("Context Assist HUD"){s=x;refresh=r;}public override object PageControl=>panel??=Build();public override bool ShowApplyButton=>true;Panel Build(){foreach(var x in new[]{"Automatisch","Links oben","Rechts oben","Links unten","Rechts unten"})corner.Items.Add(x);enabled.Checked=s.Enabled;corner.SelectedIndex=(int)s.Corner;margin.Value=s.Margin;count.Value=s.PrimaryCount;tooltip.Value=s.TooltipDelay;var l=new DynamicLayout{Padding=10,Spacing=new Eto.Drawing.Size(6,6)};l.AddRow(enabled);l.AddRow(new Label{Text="HUD-Ecke"},corner);l.AddRow(new Label{Text="Randabstand (px)"},margin);l.AddRow(new Label{Text="Hauptaktionen"},count);l.AddRow(new Label{Text="Tooltip-Verzögerung (ms)"},tooltip);return new Panel{Content=l};}public override bool OnApply(){s.Enabled=enabled.Checked==true;s.Corner=(HudCorner)Math.Max(0,corner.SelectedIndex);s.Margin=(int)margin.Value;s.PrimaryCount=(int)count.Value;s.TooltipDelay=(int)tooltip.Value;s.Save();refresh();return true;}}
